func runListConformance(t *testing.T, filename string, run func(string) []any) {
	t.Helper()
	entries, err := conformance.Load("testdata/" + filename)
	if err != nil {
		t.Fatal(err)
	}
	for _, entry := range entries {
		input := entry.Input.(string)
		want := filterInvalid(entry.Expected.([]any))
		got := run(input)
		if len(got) == 0 {
			got = []any{}
		}
		if !reflect.DeepEqual(got, want) {
			t.Errorf("%s: parse(%q)\n got: %#v\nwant: %#v", filename, input, got, want)
		}
	}
}

// filterInvalid drops the ["error","invalid"] markers the corpus uses to
// represent a dropped rule or declaration; the specification's list algorithms
// discard those items.
func filterInvalid(items []any) []any {
	result := make([]any, 0, len(items))
	for _, item := range items {
		if isInvalidMarker(item) {
			continue
		}
		result = append(result, item)
	}
	return result
}

func isInvalidMarker(value any) bool {
	items, ok := value.([]any)
	return ok && len(items) == 2 && items[0] == "error" && items[1] == "invalid"
}

func errorMarker(err error) any {
	switch {
	case errors.Is(err, parser.ErrEmpty):
		return []any{"error", "empty"}
	case errors.Is(err, parser.ErrExtraInput):
		return []any{"error", "extra-input"}
	default:
		return []any{"error", "invalid"}
	}
}

func serializeNodes(nodes []parser.Node) []any {
	result := make([]any, 0, len(nodes))
	for _, node := range nodes {
		result = append(result, serializeNode(node))
	}
	return result
}

func serializeNode(node parser.Node) any {
	switch typed := node.(type) {
	case *parser.QualifiedRule:
		block := []any{}
		if typed.Block != nil {
			block = serializeValues(typed.Block.Value)
		}
		return []any{"qualified rule", serializeValues(typed.Prelude), block}
	case *parser.AtRule:
		var block any
		if typed.Block != nil {
			block = serializeValues(typed.Block.Value)
		}
		return []any{"at-rule", typed.Name, serializeValues(typed.Prelude), block}
	case *parser.Declaration:
		return []any{"declaration", typed.Name, serializeValues(typed.Value), typed.Important}
	default:
		return nil
	}
}

func serializeValues(values []parser.ComponentValue) []any {
	result := make([]any, 0, len(values))
	for _, value := range values {
		result = append(result, serializeComponentValue(value))
	}
	return result
}

func serializeComponentValue(value parser.ComponentValue) any {
	switch typed := value.(type) {
	case parser.Token:
		return serializeToken(typed.Token)
	case *parser.Function:
		result := []any{"function", typed.Name}
		result = append(result, serializeValues(typed.Value)...)
		return result
	case *parser.Block:
		result := []any{openTag(typed.Associated)}
		result = append(result, serializeValues(typed.Value)...)
		return result
	default:
		return nil
	}
}

func openTag(tokenType tokenizer.TokenType) string {
	switch tokenType {
	case tokenizer.TokenOpenParen:
		return "()"
	case tokenizer.TokenOpenSquare:
		return "[]"
	case tokenizer.TokenOpenCurly:
		return "{}"
	default:
		return "()"
	}
}

func serializeToken(token tokenizer.Token) any {
	switch token.Type {
	case tokenizer.TokenIdent:
		return []any{"ident", token.Value}
	case tokenizer.TokenAtKeyword:
		return []any{"at-keyword", token.Value}
	case tokenizer.TokenHash:
		flag := "unrestricted"
		if token.HashFlag == tokenizer.HashID {
			flag = "id"
		}
		return []any{"hash", token.Value, flag}
	case tokenizer.TokenString:
		return []any{"string", token.Value}
	case tokenizer.TokenBadString:
		return []any{"error", "bad-string"}
	case tokenizer.TokenURL:
		return []any{"url", token.Value}
	case tokenizer.TokenBadURL:
		return []any{"error", "bad-url"}
	case tokenizer.TokenDelim:
		return token.Value
	case tokenizer.TokenNumber:
		return []any{"number", token.NumberRepresentation, token.Number, numericKind(token)}
	case tokenizer.TokenPercentage:
		return []any{"percentage", token.NumberRepresentation, token.Number, numericKind(token)}
	case tokenizer.TokenDimension:
		return []any{"dimension", token.NumberRepresentation, token.Number, numericKind(token), token.Value}
	case tokenizer.TokenWhitespace:
		return " "
	case tokenizer.TokenCDO:
		return "<!--"
	case tokenizer.TokenCDC:
		return "-->"
	case tokenizer.TokenColon:
		return ":"
	case tokenizer.TokenSemicolon:
		return ";"
	case tokenizer.TokenComma:
		return ","
	case tokenizer.TokenCloseParen:
		return []any{"error", ")"}
	case tokenizer.TokenCloseSquare:
		return []any{"error", "]"}
	case tokenizer.TokenCloseCurly:
		return []any{"error", "}"}
	case tokenizer.TokenUnicodeRange:
		return []any{"unicode-range", token.RangeStart, token.RangeEnd}
	default:
		return strings.ToLower(token.Type.String())
	}
}

func numericKind(token tokenizer.Token) string {
	if token.NumericKind == tokenizer.Number {
		return "number"
	}
	return "integer"
}
